-- 7) Update Jir status as 'Triage' for 'TRIAGE'
select count(*)
  from defecttracking.supportlog 
where status = 'TRIAGE'
	and activeflag = 1 ;
	
update defecttracking.supportlog 
set status = 'Triage', 
	updatedby = 'CIDM-7258-7', 
	updatedon = now() 
where status = 'TRIAGE'
	and activeflag = 1 ;

-- 8) Update Jir status as 'Ready For Production' for 'Ready For Production Users'
select count(*)
  from defecttracking.supportlog 
where status = 'Ready For Production Users'
	and activeflag = 1 ;
	
update defecttracking.supportlog 
set status = 'Ready For Production', 
	updatedby = 'CIDM-7258-8', 
	updatedon = now() 
where status = 'Ready For Production Users'
	and activeflag = 1 ;
